<script lang="ts">
 import type {AppState,Command} from '../lib/types';
 import {dossierTimeline,type DossierEvent} from '../lib/dossier-context';
 import {newCommandId} from '../lib/repository';
 import {safeUrl} from '../lib/domain';
 import MediaCard from './MediaCard.svelte';
 let {workspace,complexId,phaseId,caseId,commit,onSelect}:{workspace:AppState;complexId:string;phaseId?:string;caseId?:string;commit:(c:Command)=>Promise<void>;onSelect?:(id:string)=>void}=$props();
 let kind=$state('');let from=$state('');let to=$state('');let page=$state(0);let first=$state('');let second=$state('');let compare=$state(false);let sameView=$state(false);let error=$state('');
 const events=$derived(dossierTimeline(workspace,complexId,phaseId));const filtered=$derived(events.filter(e=>(!kind||e.kind===kind)&&(!from || !!e.occurredAt&&e.occurredAt>=from)&&(!to || !!e.occurredAt&&e.occurredAt.slice(0,10)<=to)));
 const photos=$derived(events.filter(e=>e.media?.kind.startsWith('image/')));const a=$derived(photos.find(e=>e.id===first));const b=$derived(photos.find(e=>e.id===second));
 $effect(()=>{kind;from;to;page=0;});
 async function attach(e:DossierEvent){if(!caseId)return;error='';try{let artifactId=e.artifactId;if(!artifactId){artifactId=`EV-${newCommandId()}`;await commit({type:'artifact.register',artifact:{id:artifactId,complexId,...(phaseId?{phaseId}:{}),kind:'event',source:e.source,text:e.text,...(e.occurredAt?{date:e.occurredAt.slice(0,10)}:{}),...(e.media?{mediaId:e.media.id}:{}),...(e.url?{url:e.url}:{})}});}await commit({type:'case.attach',caseId,artifactId});}catch(err){error=String(err);}}
</script>
<div class="filters"><label>События<select bind:value={kind}><option value="">Вся история</option>{#each ['Документы','Стройка','Реклама','Решения'] as k}<option>{k}</option>{/each}</select></label><label>С<input type="date" bind:value={from}/></label><label>По<input type="date" bind:value={to}/></label></div>
{#if error}<p class="error" role="alert">{error}</p>{/if}
{#each filtered.slice(page*25,(page+1)*25) as event}<article class="timeline-row"><span>{event.occurredAt?.slice(0,10) ?? 'Дата события неизвестна'}</span><div><p>{event.text}</p><p class="muted text-xs">{event.source} · Зафиксировано: {event.capturedAt ?? 'неизвестно'}</p><div class="actions mt-3">{#if event.media}<button class="small" onclick={()=>onSelect?.(event.media!.id)}>Показать кадр</button>{/if}{#if safeUrl(event.url)}<a class="button small" href={safeUrl(event.url)} target="_blank" rel="noopener noreferrer">Источник ↗</a>{/if}{#if caseId}<button class="small" onclick={()=>attach(event)}>Добавить событие в дело</button>{/if}</div></div></article>{:else}<p class="muted">Датированных материалов для выбранного периода нет.</p>{/each}
<div class="actions my-4"><button disabled={!page} onclick={()=>page--}>Назад</button><button disabled={(page+1)*25>=filtered.length} onclick={()=>page++}>Далее</button></div>
<section class="panel mt-5"><h3>Сравнить два периода</h3><div class="form-grid my-4"><label>Первый кадр<select bind:value={first}><option value="">Выберите снимок</option>{#each photos as p}<option value={p.id}>{p.occurredAt ?? 'Дата неизвестна'} · {p.source}</option>{/each}</select></label><label>Второй кадр<select bind:value={second}><option value="">Выберите снимок</option>{#each photos as p}<option value={p.id}>{p.occurredAt ?? 'Дата неизвестна'} · {p.source}</option>{/each}</select></label></div><button disabled={!a||!b||first===second} onclick={()=>compare=true}>Сравнить снимки</button><p class="muted mt-3">Фотографии не определяют процент готовности. Разные ракурсы сравниваются рядом.</p></section>
{#if compare&&a?.media&&b?.media}<div class="compare-overlay" role="dialog" aria-modal="true" aria-label="Сравнение снимков" tabindex="-1"><div class="page-heading"><h2>Сравнение периодов</h2><button onclick={()=>compare=false}>Закрыть сравнение</button></div><div class="two-col"><MediaCard media={a.media}/><MediaCard media={b.media}/></div><label class="check-label mt-4"><input type="checkbox" bind:checked={sameView}/> Аналитик установил сопоставимость ракурсов</label><p>{!a.occurredAt||!b.occurredAt ? 'Дата одного из снимков неизвестна — исторический вывод невозможен.' : sameView ? 'Сопоставимые ракурсы: визуальная оценка аналитика; автоматическая оценка готовности отсутствует.' : 'Сопоставимость ракурсов не установлена. Только просмотр рядом.'}</p><p class="notice mt-4">Недостаточно данных для автоматического вывода об отставании. Для R5/R6 нужны датированные документальные материалы.</p></div>{/if}
